import { useCallback, useEffect, useState } from "react";

import { StudioProApi } from "@mendix/extensions-api";
import { MicroflowIcon } from "@mendix/ide-icons/MicroflowIcon";

import { Agent } from "../../types/agent";
import { KnowledgebaseTool } from "../../types/tool";

import DialogFooter from "../components/DialogFooter";
import GroupBox from "../components/GroupBox";
import { ContentColumn, PageContainerDialog, PageContent } from "../components/PageContainers";
import TextAreaLabeled from "../components/TextAreaLabeled";
import TextInputLabeled from "../components/TextInputLabeled";
import TextInputWithButton from "../components/TextInputWithButton";

import { knowledgeBaseDocumentTypeId } from "../../main";
import { handleShowCustomBlobDocument } from "../../utils/customBlobDocumentUtils";
import { createNewKnowledgebaseTool } from "../../utils/toolUtils";
import { handleValidateKnowledgebaseTool } from "./knowledgebaseToolHandlers";
import { handleSelectDocument } from "./toolHandlers";

interface KnowledgebaseToolEditorProps {
    studioPro: StudioProApi;
    initialTool?: KnowledgebaseTool;
    agent: Agent;
    onClose: (result: KnowledgebaseTool | null) => void;
}

export type KnowledgebaseToolValidationInfo = {
    isValidName: true | string;
    isValidDescription: true | string;
    isValidDocument: true | string;
    isValidType: true | string;
    isValidCollectionIdentifier: true | string;
    isValidMaxResults: true | string;
    isValidMinSimilarity: true | string;
};

const initialValidationInfo: KnowledgebaseToolValidationInfo = {
    isValidName: true,
    isValidDescription: true,
    isValidDocument: true,
    isValidType: true,
    isValidCollectionIdentifier: true,
    isValidMaxResults: true,
    isValidMinSimilarity: true,
};

const fieldToValidationKey: Partial<Record<keyof KnowledgebaseTool, keyof KnowledgebaseToolValidationInfo>> = {
    name: "isValidName",
    description: "isValidDescription",
    document: "isValidDocument",
    collectionIdentifier: "isValidCollectionIdentifier",
    maxResults: "isValidMaxResults",
    minSimilarity: "isValidMinSimilarity",
};

const KnowledgebaseToolEditor: React.FC<KnowledgebaseToolEditorProps> = ({
    initialTool,
    studioPro,
    agent,
    onClose,
}) => {
    const [tool, setTool] = useState<KnowledgebaseTool>(initialTool || createNewKnowledgebaseTool());
    const [validationInfo, setValidationInfo] = useState(initialValidationInfo);
    const [maxResultsInput, setMaxResultsInput] = useState(
        (initialTool || createNewKnowledgebaseTool()).maxResults?.toString() ?? ""
    );
    const [minSimilarityInput, setMinSimilarityInput] = useState(
        (initialTool || createNewKnowledgebaseTool()).minSimilarity?.toString() ?? ""
    );

    const validateTool = useCallback(
        async (toolToValidate: KnowledgebaseTool): Promise<KnowledgebaseToolValidationInfo> => {
            return {
                isValidName: await handleValidateKnowledgebaseTool("name", toolToValidate, agent, studioPro),
                isValidDescription: await handleValidateKnowledgebaseTool(
                    "description",
                    toolToValidate,
                    agent,
                    studioPro
                ),
                isValidDocument: await handleValidateKnowledgebaseTool("document", toolToValidate, agent, studioPro),
                isValidType: true,
                isValidCollectionIdentifier: await handleValidateKnowledgebaseTool(
                    "collectionIdentifier",
                    toolToValidate,
                    agent,
                    studioPro
                ),
                isValidMaxResults: await handleValidateKnowledgebaseTool(
                    "maxResults",
                    toolToValidate,
                    agent,
                    studioPro
                ),
                isValidMinSimilarity: await handleValidateKnowledgebaseTool(
                    "minSimilarity",
                    toolToValidate,
                    agent,
                    studioPro
                ),
            };
        },
        [studioPro, agent]
    );

    useEffect(() => {
        if (initialTool) {
            setMaxResultsInput(initialTool.maxResults !== undefined ? initialTool.maxResults.toString() : "");
            setMinSimilarityInput(initialTool.minSimilarity !== undefined ? initialTool.minSimilarity.toString() : "");
            validateTool(initialTool).then((validationResult) => {
                setValidationInfo(validationResult);
            });
        }
    }, [initialTool, validateTool]);

    const validateOnChange = useCallback(
        async (field: keyof KnowledgebaseTool, updatedTool: KnowledgebaseTool) => {
            const validationKey = fieldToValidationKey[field];

            if (validationKey && validationInfo[validationKey] !== true) {
                const validationResult = await handleValidateKnowledgebaseTool(field, updatedTool, agent, studioPro);
                setValidationInfo((prev) => ({ ...prev, [validationKey]: validationResult }));
            }
        },
        [validationInfo, agent, studioPro]
    );

    const handleFieldChange = (field: keyof KnowledgebaseTool, value: string | boolean) => {
        if (field === "maxResults") {
            const inputValue = String(value);
            if (!/^\d*$/.test(inputValue)) {
                return;
            }

            setMaxResultsInput(inputValue);
            const parsedValue = inputValue === "" ? undefined : Number.parseInt(inputValue, 10);
            const updatedTool = {
                ...tool,
                maxResults: Number.isNaN(parsedValue) ? undefined : parsedValue,
            } as KnowledgebaseTool;
            setTool(updatedTool);
            validateOnChange(field, updatedTool);
            return;
        }

        if (field === "minSimilarity") {
            const inputValue = String(value);
            if (!/^\d*\.?\d*$/.test(inputValue)) {
                return;
            }

            setMinSimilarityInput(inputValue);
            const parsedValue = inputValue === "" || inputValue === "." ? undefined : Number.parseFloat(inputValue);
            const updatedTool = {
                ...tool,
                minSimilarity: Number.isNaN(parsedValue) ? undefined : parsedValue,
            } as KnowledgebaseTool;
            setTool(updatedTool);
            validateOnChange(field, updatedTool);
            return;
        }

        const updatedTool = { ...tool, [field]: value } as KnowledgebaseTool;
        setTool(updatedTool);
        validateOnChange(field, updatedTool);
    };

    const selectDocument = async () => {
        const document = await handleSelectDocument(studioPro, knowledgeBaseDocumentTypeId);
        if (document) {
            const updatedTool = { ...tool, document };
            setTool(updatedTool);
            validateOnChange("document", updatedTool);
        }
    };

    const showDocument = () => {
        handleShowCustomBlobDocument(studioPro, tool.document);
    };

    const handleOk = async () => {
        const validationResult = await validateTool(tool);
        console.log(validationResult);
        setValidationInfo(validationResult);

        const validationErrors = Object.values(validationResult).some((value) => value !== true);
        if (!validationErrors) {
            onClose(tool);
        }
    };

    const handleCancel = () => {
        onClose(null);
    };

    const handleHelp = () => {
        window.open(
            "https://docs.mendix.com/appstore/modules/genai/genai-for-mx/agent-commons/#adding-tools",
            "_blank",
            "noopener,noreferrer"
        );
    };

    return (
        <PageContainerDialog>
            <PageContent>
                <ContentColumn>
                    <GroupBox label="General">
                        <TextInputWithButton
                            ariaLabel={"Knowledge base"}
                            label={"Knowledge base"}
                            value={tool.document.qualifiedName}
                            icon={tool.document.qualifiedName ? <MicroflowIcon /> : undefined}
                            buttonCaption="Select..."
                            onClick={selectDocument}
                            validate={() => validationInfo.isValidDocument}
                            buttonCaptionSecondary={tool.document.qualifiedName ? "Show" : undefined}
                            onClickSecondary={tool.document.qualifiedName ? showDocument : undefined}
                        />
                        <TextInputLabeled
                            label="Collection"
                            ariaLabel="Collection identifier"
                            value={tool.collectionIdentifier}
                            onChange={(value: string) => handleFieldChange("collectionIdentifier", value)}
                            validate={() => validationInfo.isValidCollectionIdentifier}
                        />
                    </GroupBox>

                    <GroupBox label="Naming">
                        <TextInputLabeled
                            label="Name"
                            ariaLabel="Name"
                            value={tool.name}
                            onChange={(value: string) => handleFieldChange("name", value)}
                            validate={() => validationInfo.isValidName}
                        />
                        <TextAreaLabeled
                            label="Description"
                            ariaLabel="Description"
                            value={tool.description}
                            onChange={(value: string) => handleFieldChange("description", value)}
                            validate={() => validationInfo.isValidDescription}
                        />
                    </GroupBox>

                    <GroupBox label="Retrieval settings">
                        <TextInputLabeled
                            label="Max results"
                            ariaLabel="Max number of results"
                            value={maxResultsInput}
                            onChange={(value: string) => handleFieldChange("maxResults", value)}
                            validate={() => validationInfo.isValidMaxResults}
                            description="This is the highest number of data chunks that can be returned in a single retrieve. If left empty, many records could be retrieved, so it's recommended to set this number (to e.g. 5), or set the minimum similarity in the next field, or to set both."
                        />
                        <TextInputLabeled
                            label="Min similarity"
                            ariaLabel="Min similarity"
                            value={minSimilarityInput}
                            onChange={(value: string) => handleFieldChange("minSimilarity", value)}
                            validate={() => validationInfo.isValidMinSimilarity}
                            description="This is the cosine-similarity cut-off for retrievals; allowed values lie between 0 and 1. It can be used to only retrieve data chunks of high relevance. A high value (e.g. 0.8) is stricter than a low value (e.g. 0.2)."
                        />
                    </GroupBox>
                </ContentColumn>
            </PageContent>
            <DialogFooter onOk={handleOk} onCancel={handleCancel} onHelp={handleHelp} />
        </PageContainerDialog>
    );
};

export default KnowledgebaseToolEditor;
